$files = Get-ChildItem -Path D:\rawrxd\src\*.asm; foreach ($file in $files) { $content = Get-Content $file.FullName -Raw; if ($content -match "ALIGN 64" -or $content -match "ALIGN 32" -or $content -match "ALIGN 4096" -or $content -match "ALIGN 128") { $content = $content -replace "ALIGN 64", "ALIGN 16" -replace "ALIGN 32", "ALIGN 16" -replace "ALIGN 4096", "ALIGN 16" -replace "ALIGN 128", "ALIGN 16"; Set-Content $file.FullName $content } }
